// 語の成り立ちの手動監査台帳（学習者へ出す語源の本文）。
//
// アプリは全8,869語に語源メモを持っているが、学習者へ出すのは
// 「手動で確かめ、出典を添え、内容をSHA-256で固定したもの」だけという原則で運用する。
// この台帳には、そのうち本文を書き起こした・書き直した語を置く。
//  1) 語根カードでは表せない語の歴史（ideology の造語年、money のユノ・モネタ、
//     suffocation の faucēs のように語族が1つでカードを作れない語）
//  2) 「確かな語源分解を収録していない」という定型文のままだった語
//  3) 「dict と同系」のようにアプリ内部の語根IDを英単語のように書いていた語
// これ以外の語は、既存メモをそのまま出す代わりに
// [etymology-note-ledger.js] が本文のハッシュを固定する。
//
// note を1文字でも変えると品質GATEが落ち、再確認なしには公開できない。

import { ETYMOLOGY_CLEAR_WORD_NOTES } from './etymology-word-notes-clear.js'

export const ETYMOLOGY_WORD_NOTE_SCHEMA = 1

const note = (text, fingerprint) => Object.freeze({
  note: text,
  reviewedAt: '2026-09-07',
  reviewedBy: 'manual-etymology-audit',
  fingerprint,
})
// 2026-09-14 の点検: 英語の語で説明が止まっていた本文に、その語自身の由来（ラテン語などの元の語）を書き足したもの。
const renote = (text, fingerprint) => Object.freeze({
  note: text,
  reviewedAt: '2026-09-14',
  reviewedBy: 'manual-etymology-audit',
  fingerprint,
})
// 2026-09-14 の点検: 同じつづりの別の語を分け、意味どうしのつながりが分かるように書き直したもの。
const relink = (text, fingerprint) => Object.freeze({
  note: text,
  reviewedAt: '2026-09-14',
  reviewedBy: 'manual-etymology-audit',
  fingerprint,
})

// 2026-09-15 の点検: 同じつづりの別の語を独立した見出し語にしたとき、元の語の本文にもその別の語のことを書き足し、つながりの薄い本文を直したもの。
const pair = (text, fingerprint) => Object.freeze({
  note: text,
  reviewedAt: '2026-09-15',
  reviewedBy: 'manual-etymology-audit',
  fingerprint,
})

